@javanna the mapping looks fine to me:
```
{
  "my-index-000001" : {
    "mappings" : {
      "properties" : {
        "obj" : {
          "properties" : {
            "products" : {
              "properties" : {
                "manufacturer" : {
                  "type" : "text",
                  "fields" : {
                    "keyword" : {
                      "type" : "keyword",
                      "ignore_above" : 256
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
```
